"""Physics II (PHY1.002) - Electricity, part 2: chapter 3 Gauss' law and chapter 4 Electric potential.
Sources: homework sessions 2 (Gauss' law) and 3 (potential), the electrostatics lecture (2025-26), midterm tutoring slides."""
import math
import numpy as np
from phys_common import *
from phys_verify import integrate, face_flux, ball_field, disk_potential
import figs

H2 = "Homework session 2"
H3 = "Homework session 3"
GEN = lambda s: "Generated, same style as: " + s
k = K_E

# =============================================================================================== chapter 3
def ch3(B):
    c = "c3"
    # ---------------------------------------------------------------- electric flux
    for E, A, th in [(3.0e3, 0.20, 60.0), (500.0, 0.50, 30.0), (1.2e4, 0.04, 45.0)]:
        ph = E * A * math.cos(math.radians(th))
        mcq_num(B, c, "Electric flux", 1, "A uniform field of %s N/C passes through a flat surface of area %s m². The angle between the field and the surface NORMAL is %s°. What is the flux through the surface?" % (sci(E), sci(A), sci(th)),
                ph, [E * A * math.sin(math.radians(th)), E * A, E * A * math.tan(math.radians(th)), E * A / 2, E * A * math.cos(math.radians(th)) * 2], "N m^2/C", ex("$\\Phi=EA\\cos\\theta$ with $\\theta$ measured from the normal (area vector): $\\Phi=%s\\times%s\\times\\cos%s^\\circ=%s\\,\\mathrm{N\\,m^2/C}$." % (sci(E), sci(A), sci(th), sci(ph)), "If the angle is given from the SURFACE, use the complement."), GEN("Electrostatics lecture, 3.1 Electric flux"), "gen", sig=3)
    mcq_pick(B, c, "Electric flux", 1, "A flat surface is parallel to a uniform electric field. The flux through it is", ["zero", "$EA$", "$-EA$", "$EA/2$"], 0, ex("The field lines do not cross the surface: the normal is perpendicular to $\\vec E$, so $\\cos90^\\circ=0$ and $\\Phi=0$."), "Electrostatics lecture, 3.1 Electric flux", "concept")
    q = 2.0e-9
    ph = q / EPS0
    mcq_num(B, c, "Gauss' law", 1, "A closed surface encloses a point charge of $+2.0\\,\\mathrm{nC}$. What is the net electric flux through it?", ph, [ph / 6, k * q, ph * 4 * math.pi, q * EPS0], "N m^2/C", ex("Gauss' law: $\\Phi=\\dfrac{q_{\\text{enc}}}{\\varepsilon_0}=\\dfrac{2.0\\times10^{-9}}{8.85\\times10^{-12}}=226\\,\\mathrm{N\\,m^2/C}$, whatever the shape of the surface."), GEN("Electrostatics lecture, 3.2 Gauss' law"), "gen", sig=3)
    qs = [5.0e-9, -3.0e-9]; q_out = 4.0e-9
    ph = sum(qs) / EPS0
    mcq_num(B, c, "Gauss' law", 2, "A cube encloses charges of $+5.0\\,\\mathrm{nC}$ and $-3.0\\,\\mathrm{nC}$; a $+4.0\\,\\mathrm{nC}$ charge sits outside the cube. What is the net flux through the cube's surface?", ph, [(sum(qs) + q_out) / EPS0, 6.0e-9 / EPS0, (5.0e-9 + 3.0e-9) / EPS0, ph / 6], "N m^2/C", ex("Only the ENCLOSED charge counts: $q_{\\text{enc}}=5.0-3.0=2.0\\,\\mathrm{nC}$, so $\\Phi=\\dfrac{2.0\\times10^{-9}}{8.85\\times10^{-12}}=226\\,\\mathrm{N\\,m^2/C}$.", "The outside charge makes field lines enter and leave the cube: its net contribution to the flux is zero."), GEN("Electrostatics lecture, 3.2 Gauss' law"), "gen", sig=3)
    a, q = 0.20, 1.0e-9
    ph6 = face_flux(q, a, EPS0)
    check(ph6, q / (6 * EPS0), 2e-3, "flux through one face by integrating E.dA")
    mcq_num(B, c, "Gauss' law", 2, "A point charge of $1.0\\,\\mathrm{nC}$ is at the centre of a cube of side $0.20\\,\\mathrm{m}$. What is the flux through ONE face?", q / (6 * EPS0), [q / EPS0, q / (6 * EPS0) * 0.04, q / (4 * EPS0), q / (8 * EPS0)], "N m^2/C", ex("By symmetry the six faces share the total flux equally: $\\Phi_{\\text{face}}=\\dfrac{q}{6\\varepsilon_0}=\\dfrac{1.0\\times10^{-9}}{6(8.85\\times10^{-12})}=18.8\\,\\mathrm{N\\,m^2/C}$.", "The side of the cube does not matter. A direct numerical integration of $\\vec E\\cdot\\mathrm{d}\\vec A$ over one face gives the same value."), GEN("Electrostatics lecture, 3.2 Gauss' law"), "gen", sig=3)
    mcq_pick(B, c, "Gauss' law", 2, "Gauss' law $\\oint\\vec E\\cdot\\mathrm{d}\\vec A=q_{\\text{enc}}/\\varepsilon_0$ is TRUE for", ["any closed surface, but it is only USEFUL for finding $E$ when the charge distribution is symmetric", "spherical surfaces only", "symmetric charge distributions only", "uniform fields only"], 0, ex("It is a general law (one of Maxwell's equations). Symmetry (spherical, cylindrical, planar) lets us pull $E$ out of the integral and solve for it."), "Electrostatics lecture, 3.2 Gauss' law", "concept")
    # ---------------------------------------------------------------- symmetric distributions
    for lam, r in [(2.0e-8, 0.060), (5.0e-9, 0.25)]:
        E = lam / (2 * math.pi * EPS0 * r)
        L = 4000 * r
        En = integrate(lambda x: k * lam * r / (r * r + x * x) ** 1.5, -L, L)           # a very long line, integrated: second route
        check(E, En, 2e-3, "infinite line by integrating Coulomb's law")
        mcq_num(B, c, "Gauss' law", 2, "A very long straight wire has a uniform linear charge density of %s C/m. What is the electric field magnitude %s m from the wire?" % (sci(lam), sci(r)), E, [lam / (4 * math.pi * EPS0 * r ** 2), lam / (2 * math.pi * EPS0 * r ** 2), lam / (EPS0 * r), E / 2], "N/C", ex("Cylindrical Gaussian surface of radius $r$ and length $\\ell$: $E(2\\pi r\\ell)=\\dfrac{\\lambda\\ell}{\\varepsilon_0}$, so $E=\\dfrac{\\lambda}{2\\pi\\varepsilon_0r}=%s\\,\\mathrm{N/C}$." % sci(E), "The field falls off as $1/r$. Integrating Coulomb's law along a very long wire gives the same result."), GEN(H2 + ", Q2"), "gen", sig=3)
    lam, R = 2.00e-8, 0.0300
    E_in, E_out = 0.0, lam / (2 * math.pi * EPS0 * 2 * R)
    mcq_num(B, c, "Gauss' law", 2, "A long thin-walled metal tube of radius $R=3.00\\,\\mathrm{cm}$ has a charge per unit length $\\lambda=2.00\\times10^{-8}\\,\\mathrm{C/m}$. What is the field magnitude at radial distance $r=2.00R$?", E_out, [E_out * 2, E_out / 2, lam / (4 * math.pi * EPS0 * (2 * R) ** 2), lam / (2 * math.pi * EPS0 * R)], "N/C", ex("Outside the tube a Gaussian cylinder encloses $\\lambda\\ell$: $E=\\dfrac{\\lambda}{2\\pi\\varepsilon_0r}=\\dfrac{2.00\\times10^{-8}}{2\\pi(8.85\\times10^{-12})(0.0600)}=5.99\\times10^{3}\\,\\mathrm{N/C}$."), H2 + ", Q2(b)", sig=3)
    mcq_num(B, c, "Gauss' law", 2, "For the same metal tube ($R=3.00\\,\\mathrm{cm}$, $\\lambda=2.00\\times10^{-8}\\,\\mathrm{C/m}$), what is the field magnitude at $r=R/2$ (inside the tube)?", 0.0, [lam / (2 * math.pi * EPS0 * R / 2), lam / (2 * math.pi * EPS0 * R) / 2, lam / (2 * math.pi * EPS0 * R), k * lam], "N/C", ex("A Gaussian cylinder inside the tube encloses no charge (the charge sits on the conductor's surface), so $E=0$."), H2 + ", Q2(a)", sig=3)
    # two parallel lines of charge
    lam1, lam2, Lx = 6.0e-6, -2.0e-6, 0.080
    xz = brentq_zero(lambda x: lam1 / x + lam2 / (x - Lx), Lx + 1e-6, 1.0)
    check(xz, 0.12, 1e-8)
    mcq_num(B, c, "Gauss' law", 3, "Two very long parallel lines of charge are $8.0\\,\\mathrm{cm}$ apart: line 1 has $+6.0\\,\\mu\\mathrm{C/m}$ (at $x=0$) and line 2 has $-2.0\\,\\mu\\mathrm{C/m}$ (at $x=8.0\\,\\mathrm{cm}$). At what $x$ along the line joining them is the net field zero?", xz * 100, [4.0, 2.0, 6.0, 10.0], "cm", ex("Between the lines both fields point the same way (away from the positive line, towards the negative one), so they cannot cancel there. Cancellation needs a point beyond the line with the smaller $|\\lambda|$.", "At $x>8.0\\,\\mathrm{cm}$: $\\dfrac{\\lambda_1}{x}=\\dfrac{|\\lambda_2|}{x-L}$, i.e. $\\dfrac{6.0}{x}=\\dfrac{2.0}{x-0.080}\\Rightarrow x=0.12\\,\\mathrm{m}=12\\,\\mathrm{cm}$."), H2 + ", Q3", sig=3)
    for sig_, kind in [(7.00e-22, "plates"), (1.77e-22, "sheets")]:
        if kind == "plates":
            E = sig_ / EPS0
            mcq_num(B, c, "Charged plates and conductors", 2, "Two large thin metal plates are parallel and close together; on their inner faces they carry excess surface charge densities of equal magnitude $7.00\\times10^{-22}\\,\\mathrm{C/m^2}$ and opposite sign. What is the field magnitude BETWEEN the plates?", E, [E / 2, E * 2, 0.0, sig_ / (4 * math.pi * EPS0)], "N/C", ex("For a conductor the field next to the surface is $\\sigma/\\varepsilon_0$, and between oppositely charged plates the fields of the two plates add: $E=\\dfrac{\\sigma}{\\varepsilon_0}=\\dfrac{7.00\\times10^{-22}}{8.85\\times10^{-12}}=7.91\\times10^{-11}\\,\\mathrm{N/C}$ (zero outside the plates)."), H2 + ", Q4(c)", sig=3)
        else:
            E = sig_ / EPS0
            mcq_num(B, c, "Charged plates and conductors", 2, "Two large parallel non-conducting sheets carry identical positive uniform surface charge densities $\\sigma=1.77\\times10^{-22}\\,\\mathrm{C/m^2}$. What is the field magnitude ABOVE both sheets (outside)?", E, [E / 2, E * 2, 0.0, sig_ / (4 * math.pi * EPS0)], "N/C", ex("Each sheet gives $\\dfrac{\\sigma}{2\\varepsilon_0}$, directed away from it. Outside both sheets the two fields point the same way and add: $E=\\dfrac{\\sigma}{\\varepsilon_0}=\\dfrac{1.77\\times10^{-22}}{8.85\\times10^{-12}}=2.00\\times10^{-11}\\,\\mathrm{N/C}$. Between the sheets they cancel."), H2 + ", Q5(a)", sig=3)
    mcq_pick(B, c, "Charged plates and conductors", 1, "Two large parallel sheets carry the SAME uniform positive surface charge density. The field BETWEEN them is", ["zero", "$\\sigma/2\\varepsilon_0$", "$\\sigma/\\varepsilon_0$", "$2\\sigma/\\varepsilon_0$"], 0, ex("Between the sheets the field of each points towards the other sheet, so the two cancel; outside they add to $\\sigma/\\varepsilon_0$."), H2 + ", Q5(b)", "src")
    sg = 3.0e-6
    mcq_num(B, c, "Charged plates and conductors", 1, "An infinite non-conducting sheet carries a uniform surface charge density of $3.0\\,\\mu\\mathrm{C/m^2}$. What is the field magnitude near the sheet?", sg / (2 * EPS0), [sg / EPS0, sg / (4 * math.pi * EPS0), sg / (2 * EPS0) / 2, sg * 2 / EPS0], "N/C", ex("Gaussian 'pillbox': $2EA=\\dfrac{\\sigma A}{\\varepsilon_0}$, so $E=\\dfrac{\\sigma}{2\\varepsilon_0}=\\dfrac{3.0\\times10^{-6}}{2(8.85\\times10^{-12})}=1.7\\times10^{5}\\,\\mathrm{N/C}$, independent of the distance from the sheet."), GEN(H2 + ", Q5"), "gen", sig=2)
    sg2 = 2.0e-6
    mcq_num(B, c, "Charged plates and conductors", 2, "The surface of a charged conductor carries $2.0\\,\\mu\\mathrm{C/m^2}$. What is the field just outside the surface?", sg2 / EPS0, [sg2 / (2 * EPS0), sg2 * 2 / EPS0, sg2 / (4 * math.pi * EPS0), 0.0], "N/C", ex("For a conductor $E=\\dfrac{\\sigma}{\\varepsilon_0}=\\dfrac{2.0\\times10^{-6}}{8.85\\times10^{-12}}=2.3\\times10^{5}\\,\\mathrm{N/C}$, perpendicular to the surface (twice the field of a non-conducting sheet with the same $\\sigma$; inside the conductor $E=0$)."), GEN("Electrostatics lecture, 3.3 A charged isolated conductor"), "gen", sig=2)
    # spheres: solid sphere inside a conducting shell (HW2 Q6)
    a_ = 0.0200; q1 = 5.00e-15
    for lab, r in [("a/2", a_ / 2), ("a", a_), ("1.5a", 1.5 * a_)]:
        E = k * q1 * r / a_ ** 3 if r < a_ else k * q1 / r ** 2
        En = ball_field(q1, a_, r, 1 / (4 * math.pi * k)) if r != a_ else k * q1 / a_ ** 2
        check(E, En, 1e-5, "ball field by integrating Coulomb's law")
        mcq_num(B, c, "Gauss' law", 2, "A solid sphere of radius $a=2.00\\,\\mathrm{cm}$ carries a net charge $q_1=5.00\\,\\mathrm{fC}$ uniformly distributed through its volume. It is concentric with a conducting spherical shell (inner radius $2a$, outer radius $2.4a$, net charge $-q_1$). What is the field magnitude at $r=%s$?" % lab, E,
                [k * q1 / r ** 2 if r < a_ else k * q1 * r / a_ ** 3, E * 2, E / 2, 0.0], "N/C",
                ex("Gaussian sphere of radius $r$: $E\\,4\\pi r^2=\\dfrac{q_{\\text{enc}}}{\\varepsilon_0}$." + ("\nInside the uniform sphere $q_{\\text{enc}}=q_1\\dfrac{r^3}{a^3}$, so $E=\\dfrac{kq_1r}{a^3}=%s\\,\\mathrm{N/C}$ (grows linearly with $r$)." % sci(E) if r < a_ else "\nOutside (or at the surface) the whole charge counts: $E=\\dfrac{kq_1}{r^2}=%s\\,\\mathrm{N/C}$." % sci(E)), "A numerical integration of Coulomb's law over the volume gives the same field."), H2 + ", Q6", sig=3)
    mcq_num(B, c, "Gauss' law", 2, "In the same arrangement (solid sphere $q_1=5.00\\,\\mathrm{fC}$, radius $a=2.00\\,\\mathrm{cm}$; shell between $2a$ and $2.4a$ with net charge $-q_1$), what is the field magnitude at $r=3.5a$, outside everything?", 0.0, [k * q1 / (3.5 * a_) ** 2, k * q1 / (2.4 * a_) ** 2, k * q1 / (2 * a_) ** 2, k * q1 / a_ ** 2], "N/C", ex("Net enclosed charge $=q_1+(-q_1)=0$, so $E=0$ outside the whole system."), H2 + ", Q6(f)", sig=3)
    mcq_num(B, c, "Charged plates and conductors", 2, "In the same arrangement (solid sphere with $+5.00\\,\\mathrm{fC}$ inside a conducting shell of net charge $-5.00\\,\\mathrm{fC}$), what is the charge on the INNER surface of the shell, in fC?", -5.0, [5.0, 0.0, -10.0, 2.5], "fC", ex("The field inside the conducting material of the shell must be zero. A Gaussian sphere inside the shell must enclose zero charge, so the inner surface carries $-q_1=-5.00\\,\\mathrm{fC}$. The outer surface then carries $-5.00-(-5.00)=0$."), H2 + ", Q6(g, h)", sig=3)
    # generated: sphere fields
    for Q, R, r in [(4.0e-9, 0.10, 0.25), (6.0e-9, 0.05, 0.12)]:
        E = k * Q / r ** 2
        mcq_num(B, c, "Gauss' law", 2, "A conducting sphere of radius %s m carries a charge of %s nC. What is the electric field at a distance of %s m from its centre?" % (sci(R), sci(Q * 1e9), sci(r)), E, [k * Q / (r - R) ** 2, k * Q / R ** 2, k * Q / r, E / 2], "N/C", ex("Outside a spherical charge distribution the field is that of a point charge at the centre: $E=\\dfrac{kQ}{r^2}=\\dfrac{(8.99\\times10^9)(%s\\times10^{-9})}{%s^2}=%s\\,\\mathrm{N/C}$. The distance is measured from the CENTRE." % (sci(Q * 1e9), sci(r), sci(E))), GEN(H2 + ", Q6"), "gen", sig=3)
    for Q, R, r in [(5.0e-9, 0.10, 0.04), (8.0e-9, 0.20, 0.15)]:
        E = k * Q * r / R ** 3
        mcq_num(B, c, "Gauss' law", 3, "A solid NON-conducting sphere of radius %s m carries a uniform volume charge of total %s nC. What is the field at %s m from the centre (inside)?" % (sci(R), sci(Q * 1e9), sci(r)), E, [k * Q / r ** 2, k * Q / R ** 2, k * Q * r / R ** 2, E * 2], "N/C", ex("A Gaussian sphere of radius $r<R$ encloses $q_{\\text{enc}}=Q\\dfrac{r^3}{R^3}$, so $E=\\dfrac{kQr}{R^3}=\\dfrac{(8.99\\times10^9)(%s\\times10^{-9})(%s)}{%s^3}=%s\\,\\mathrm{N/C}$." % (sci(Q * 1e9), sci(r), sci(R), sci(E))), GEN(H2 + ", Q6"), "gen", sig=3)
    mcq_pick(B, c, "Charged plates and conductors", 1, "Inside a conductor in electrostatic equilibrium, the electric field is", ["zero everywhere in the material, and any excess charge sits on the surface", "uniform and non-zero", "radial and proportional to $r$", "equal to $\\sigma/\\varepsilon_0$"], 0, ex("If $\\vec E$ were non-zero the free charges would move; at equilibrium $\\vec E=0$ inside, so by Gauss' law there is no net charge in the interior."), "Electrostatics lecture, 3.3 A charged isolated conductor", "concept")
    mcq_pick(B, c, "Charged plates and conductors", 3, "A point charge $+q$ is placed at the centre of a neutral conducting spherical shell. The charges on the inner and outer surfaces of the shell are", ["$-q$ on the inner surface and $+q$ on the outer surface", "$0$ on both surfaces", "$+q$ on the inner surface and $-q$ on the outer surface", "$-q$ on both surfaces"], 0, ex("A Gaussian sphere inside the metal must enclose zero net charge, so the inner surface carries $-q$; the shell is neutral overall, so $+q$ appears on the outer surface (and the field outside is $kq/r^2$ as if the shell were absent)."), "Electrostatics lecture, 3.3 A charged isolated conductor", "concept")
    mcq_pick(B, c, "Electric flux", 2, "The flux through a closed spherical surface centred on a point charge $q$ changes when", ["the charge $q$ is doubled", "the radius of the sphere is doubled", "the charge is moved off-centre but stays inside", "the sphere is replaced by a cube enclosing the same charge"], 0, ex("$\\Phi=q_{\\text{enc}}/\\varepsilon_0$ depends only on the enclosed charge: neither the radius, the shape nor the position inside matters."), "Electrostatics lecture, 3.2 Gauss' law", "concept")

def brentq_zero(f, lo, hi):
    from scipy.optimize import brentq
    return brentq(f, lo, hi)

# =============================================================================================== chapter 4
def ch4(B):
    c = "c4"
    # ---------------------------------------------------------------- homework 3
    # V_B - V_A for E_x = 4 x
    dV = -integrate(lambda x: 4.0 * x, 0.0, 4.00)
    check(dV, -0.5 * 4.0 * 4.00 ** 2)
    mcq_num(B, c, "Potential and field", 2, "In a region the electric field has components $E_y=E_z=0$ and $E_x=(4.00\\,\\mathrm{N/C})\\,x$ ($x$ in metres). Point A is on the $y$ axis at $y=3.00\\,\\mathrm{m}$ and point B on the $x$ axis at $x=4.00\\,\\mathrm{m}$. What is $V_B-V_A$?", dV, [-dV, 0.0, -4.0 * 4.0, -2.0 * 4.0 * 3.0], "V", ex("$V_B-V_A=-\\int_A^B\\vec E\\cdot\\mathrm{d}\\vec l$. Choose the path A to the origin (along $y$, where $E_y=0$, no contribution) and then along $x$ to B.", "$V_B-V_A=-\\int_0^{4.00}4.00\\,x\\,\\mathrm{d}x=-2.00(4.00)^2=-32.0\\,\\mathrm{V}$."), H3 + ", Q1", sig=3)
    p = 1.47 * 3.34e-30; r = 52.0e-9
    V = k * p / r ** 2
    mcq_num(B, c, "Potential of point charges", 2, "The ammonia molecule has a permanent dipole moment of $1.47\\,\\mathrm{D}$ ($1\\,\\mathrm{D}=3.34\\times10^{-30}\\,\\mathrm{C\\,m}$). What is the electric potential due to it at a point $52.0\\,\\mathrm{nm}$ away along the axis of the dipole ($V=0$ at infinity)?", V, [V * 2, V / 2, V * 4, V / 4], "V", ex("$p=1.47\\times3.34\\times10^{-30}=4.91\\times10^{-30}\\,\\mathrm{C\\,m}$.", "Dipole potential on the axis: $V=\\dfrac{kp\\cos\\theta}{r^2}=\\dfrac{(8.99\\times10^9)(4.91\\times10^{-30})}{(52.0\\times10^{-9})^2}=1.63\\times10^{-5}\\,\\mathrm{V}$ (it falls off as $1/r^2$, faster than a point charge's $1/r$)."), H3 + ", Q3", sig=3)
    Q, Rr = -25.6e-12, 0.0371
    V = k * Q / Rr
    mcq_num(B, c, "Potential of point charges", 2, "A plastic rod carrying a uniformly distributed charge $Q=-25.6\\,\\mathrm{pC}$ is bent into a circular arc of radius $R=3.71\\,\\mathrm{cm}$ and central angle $120^\\circ$. What is the electric potential at the centre of curvature P (with $V=0$ at infinity)?", V, [V * 3, V / 3, k * Q / (Rr * math.sin(math.radians(60))), -V], "V", ex("Potential is a SCALAR and every element $\\mathrm{d}q$ is at the same distance $R$ from P: $V=\\dfrac{k}{R}\\int\\mathrm{d}q=\\dfrac{kQ}{R}=\\dfrac{(8.99\\times10^9)(-25.6\\times10^{-12})}{0.0371}=-6.20\\,\\mathrm{V}$. The angle of the arc does not matter."), H3 + ", Q4", sig=3)
    # V = 2x^2 - 3y^2: E at (3, 2)
    Ex, Ey = -4.0 * 3.0, 6.0 * 2.0
    mag = math.hypot(Ex, Ey)
    mcq_num(B, c, "Potential and field", 2, "In the $xy$ plane the electric potential is $V=(2.0\\,\\mathrm{V/m^2})x^2-(3.0\\,\\mathrm{V/m^2})y^2$. What is the magnitude of the electric field at the point $(3.0\\,\\mathrm{m},\\,2.0\\,\\mathrm{m})$?", mag, [abs(Ex) + abs(Ey), math.hypot(4.0 * 3.0, 6.0 * 3.0), 2.0 * 9 - 3.0 * 4, abs(Ex)], "V/m", ex("$\\vec E=-\\nabla V$: $E_x=-\\dfrac{\\partial V}{\\partial x}=-4.0x=-12\\,\\mathrm{V/m}$, $E_y=-\\dfrac{\\partial V}{\\partial y}=+6.0y=+12\\,\\mathrm{V/m}$.", "$\\vec E=(-12\\,\\hat i+12\\,\\hat j)\\,\\mathrm{V/m}$, magnitude $\\sqrt{12^2+12^2}=17\\,\\mathrm{V/m}$, directed $135^\\circ$ from $+x$."), H3 + ", Q5", sig=2)
    # tiny spheres joined by a string (cut)
    mA, mB, qq, d = 5.00e-3, 10.0e-3, 5.00e-6, 1.00
    U = k * qq * qq / d; F = k * qq * qq / d ** 2
    vA = math.sqrt(U / (0.5 * mA + 0.5 * mB * (mA / mB) ** 2)); vB = vA * mA / mB
    check(0.5 * mA * vA ** 2 + 0.5 * mB * vB ** 2, U); check(mA * vA, mB * vB)
    mcq_num(B, c, "Electric potential energy", 2, "Two tiny metal spheres A ($5.00\\,\\mathrm{g}$) and B ($10.0\\,\\mathrm{g}$) carry equal positive charges $q=5.00\\,\\mu\\mathrm{C}$ and are tied by a string of length $d=1.00\\,\\mathrm{m}$. What is the electric potential energy of the system?", U, [k * qq / d, 2 * U, U / 2, k * qq * qq / d ** 2], "J", ex("$U=\\dfrac{kq_Aq_B}{d}=\\dfrac{(8.99\\times10^9)(5.00\\times10^{-6})^2}{1.00}=0.225\\,\\mathrm{J}$."), H3 + ", Q7(a)", sig=3)
    note(H3 + ", Q7", "the charge of the two spheres is printed as 5.00 mC; the textbook problem has 5.00 microcoulombs (with 5.00 mC the potential energy would be 2.2x10^5 J). The questions use 5.00 microcoulombs.")
    mcq_num(B, c, "Electric potential energy", 3, "The string between spheres A ($5.00\\,\\mathrm{g}$) and B ($10.0\\,\\mathrm{g}$), each carrying $5.00\\,\\mu\\mathrm{C}$ and $1.00\\,\\mathrm{m}$ apart, is cut. What is the acceleration of sphere A at that instant?", F / mA, [F / mB, F / (mA + mB), F, 2 * F / mA], "m/s^2", ex("Coulomb force $F=\\dfrac{kq^2}{d^2}=0.225\\,\\mathrm{N}$ on each sphere.", "$a_A=\\dfrac{F}{m_A}=\\dfrac{0.225}{0.00500}=45.0\\,\\mathrm{m/s^2}$ and $a_B=22.5\\,\\mathrm{m/s^2}$."), H3 + ", Q7(b)", sig=3)
    mcq_num(B, c, "Electric potential energy", 3, "After a long time the two spheres of the previous problem (A: $5.00\\,\\mathrm{g}$, B: $10.0\\,\\mathrm{g}$, each $5.00\\,\\mu\\mathrm{C}$, initially $1.00\\,\\mathrm{m}$ apart) are far apart. What is the final speed of sphere A?", vA, [math.sqrt(2 * U / mA), math.sqrt(U / mA), vB, math.sqrt(2 * U / (mA + mB))], "m/s", ex("Momentum conservation (starting at rest): $m_Av_A=m_Bv_B\\Rightarrow v_B=\\dfrac{v_A}{2}$.", "Energy conservation: $U=\\tfrac12m_Av_A^2+\\tfrac12m_Bv_B^2=\\tfrac12(0.005)v_A^2+\\tfrac12(0.010)\\dfrac{v_A^2}{4}=0.00375\\,v_A^2$.", "$v_A=\\sqrt{\\dfrac{0.225}{0.00375}}=7.74\\,\\mathrm{m/s}$ and $v_B=3.87\\,\\mathrm{m/s}$."), H3 + ", Q7(c)", sig=3)
    # concentric shells (Q8)
