    V4 = k * (q1 + q2) / 4.00; V07 = k * q1 / 0.700 + k * q2 / R2; V02 = k * q1 / R1 + k * q2 / R2
    mcq_num(B, c, "Potential of conductors", 2, "Two concentric conducting spherical shells have radii $R_1=0.500\\,\\mathrm{m}$ and $R_2=1.00\\,\\mathrm{m}$ and carry uniform charges $q_1=2.00\\,\\mu\\mathrm{C}$ (inner) and $q_2=1.00\\,\\mu\\mathrm{C}$ (outer). With $V=0$ at infinity, what is $V$ at $r=4.00\\,\\mathrm{m}$?", V4, [k * q1 / 4.0, k * (q1 + q2) / 4.0 ** 2, V4 * 2, k * q2 / 4.0], "V", ex("Outside both shells the system acts as a point charge $q_1+q_2$: $V=\\dfrac{k(q_1+q_2)}{r}=\\dfrac{(8.99\\times10^9)(3.00\\times10^{-6})}{4.00}=6.74\\times10^{3}\\,\\mathrm{V}$."), H3 + ", Q8(d)", sig=3)
    mcq_num(B, c, "Potential of conductors", 3, "For the same shells ($R_1=0.500\\,\\mathrm{m}$ with $2.00\\,\\mu\\mathrm{C}$, $R_2=1.00\\,\\mathrm{m}$ with $1.00\\,\\mu\\mathrm{C}$), what is the potential at $r=0.700\\,\\mathrm{m}$, between the shells?", V07, [k * (q1 + q2) / 0.700, k * q1 / 0.700, V07 / 2, k * q1 / 0.700 - k * q2 / R2], "V", ex("Between the shells the inner shell acts as a point charge, while the outer shell (all of whose charge is at $R_2>r$) contributes the constant $\\dfrac{kq_2}{R_2}$.", "$V=\\dfrac{kq_1}{r}+\\dfrac{kq_2}{R_2}=\\dfrac{(8.99\\times10^9)(2.00\\times10^{-6})}{0.700}+\\dfrac{(8.99\\times10^9)(1.00\\times10^{-6})}{1.00}=2.57\\times10^{4}+8.99\\times10^{3}=3.47\\times10^{4}\\,\\mathrm{V}$."), H3 + ", Q8(f)", sig=3)
    mcq_num(B, c, "Potential of conductors", 3, "For the same shells, what is the potential at $r=0.200\\,\\mathrm{m}$, inside the inner shell?", V02, [0.0, k * q1 / 0.200, k * (q1 + q2) / 0.200, V07], "V", ex("Inside the inner shell $E=0$, so the potential is constant and equal to its value on the inner shell: $V=\\dfrac{kq_1}{R_1}+\\dfrac{kq_2}{R_2}=3.60\\times10^4+8.99\\times10^3=4.50\\times10^{4}\\,\\mathrm{V}$ (the same at $r=0$)."), H3 + ", Q8(h, i)", sig=3)
    # ---------------------------------------------------------------- generated: potential of point charges and energy
    for q_, r_ in [(5.0e-9, 0.30), (-2.0e-9, 0.10), (12.0e-9, 0.60)]:
        V = k * q_ / r_
        mcq_num(B, c, "Potential of point charges", 1, "What is the electric potential %s m from a point charge of %s nC (V = 0 at infinity)?" % (sci(r_), sci(q_ * 1e9)), V, [k * abs(q_) / r_ ** 2, -V, V / 2, V * r_], "V", ex("$V=\\dfrac{kq}{r}=\\dfrac{(8.99\\times10^9)(%s\\times10^{-9})}{%s}=%s\\,\\mathrm{V}$ (a scalar: the sign of the charge is kept)." % (sci(q_ * 1e9), sci(r_), sci(V))), GEN(H3 + ", Q2"), "gen", sig=3)
    qs = [3.0e-9, -5.0e-9, 4.0e-9]; ps = [(0.0, 0.0), (0.20, 0.0), (0.0, 0.15)]
    Vp = sum(k * q_ / math.hypot(0.10 - x, 0.05 - y) for q_, (x, y) in zip(qs, ps))
    Vn = sum(k * q_ / np.linalg.norm(np.array([0.10, 0.05]) - np.array(p_)) for q_, p_ in zip(qs, ps))
    check(Vp, Vn)
    d_ = [math.hypot(0.10 - x, 0.05 - y) for x, y in ps]
    mcq_num(B, c, "Potential of point charges", 2, "Point charges of $+3.0\\,\\mathrm{nC}$ at $(0,0)$, $-5.0\\,\\mathrm{nC}$ at $(0.20\\,\\mathrm{m},0)$ and $+4.0\\,\\mathrm{nC}$ at $(0,0.15\\,\\mathrm{m})$ are fixed. What is the potential at the point $(0.10\\,\\mathrm{m},\\,0.05\\,\\mathrm{m})$?", Vp, [k * sum(qs) / d_[0], abs(k * qs[0] / d_[0]) + abs(k * qs[1] / d_[1]) + abs(k * qs[2] / d_[2]), k * sum(qs) / (sum(d_) / 3), Vp * 2], "V", ex("Distances: $r_1=\\sqrt{0.10^2+0.05^2}=0.112\\,\\mathrm{m}$, $r_2=\\sqrt{0.10^2+0.05^2}=0.112\\,\\mathrm{m}$, $r_3=\\sqrt{0.10^2+0.10^2}=0.141\\,\\mathrm{m}$.", "Potentials add as numbers (signs included): $V=k\\left(\\dfrac{q_1}{r_1}+\\dfrac{q_2}{r_2}+\\dfrac{q_3}{r_3}\\right)=%s\\,\\mathrm{V}$." % sci(Vp)), GEN(H3 + ", Q2"), "gen", sig=3)
    for q1_, q2_, r_ in [(2.0e-6, -3.0e-6, 0.50), (4.0e-6, 4.0e-6, 0.20)]:
        Uu = k * q1_ * q2_ / r_
        mcq_num(B, c, "Electric potential energy", 2, "Two point charges of %s μC and %s μC are %s m apart. What is the electric potential energy of the pair (zero at infinite separation)?" % (sci(q1_ * 1e6), sci(q2_ * 1e6), sci(r_)), Uu, [-Uu, k * q1_ * q2_ / r_ ** 2, Uu / 2, k * (q1_ + q2_) / r_], "J", ex("$U=\\dfrac{kq_1q_2}{r}=\\dfrac{(8.99\\times10^9)(%s\\times10^{-6})(%s\\times10^{-6})}{%s}=%s\\,\\mathrm{J}$; negative for opposite charges (bound), positive for like charges (work is needed to bring them together)." % (sci(q1_ * 1e6), sci(q2_ * 1e6), sci(r_), sci(Uu))), GEN(H3 + ", Q7"), "gen", sig=3)
    qa, a_ = 2.0e-9, 0.10
    U3 = k * qa * qa / a_ * 3
    Un = sum(k * qa * qa / np.linalg.norm(np.array(p1) - np.array(p2)) for p1, p2 in [((0, 0), (a_, 0)), ((0, 0), (a_ / 2, a_ * math.sqrt(3) / 2)), ((a_, 0), (a_ / 2, a_ * math.sqrt(3) / 2))])
    check(U3, Un)
    mcq_num(B, c, "Electric potential energy", 3, "Three equal charges of $2.0\\,\\mathrm{nC}$ are placed at the corners of an equilateral triangle of side $0.10\\,\\mathrm{m}$. How much work was needed to assemble them from far apart?", U3, [U3 / 3, U3 * 2, U3 / 3 * 2, k * qa * qa / a_ ** 2 * 3], "J", ex("The potential energy is the sum over the THREE pairs: $U=3\\,\\dfrac{kq^2}{a}=3\\,\\dfrac{(8.99\\times10^9)(2.0\\times10^{-9})^2}{0.10}=1.1\\times10^{-6}\\,\\mathrm{J}$ (equal to the work needed to assemble the charges)."), GEN(H3 + ", Q6"), "gen", sig=2)
    # accelerating potential
    for V_, part, m_, qn in [(1500.0, "electron", M_E, E_CH), (5000.0, "proton", M_P, E_CH)]:
        v = math.sqrt(2 * qn * V_ / m_)
        mcq_num(B, c, "Energy and potential difference", 2, "A %s is accelerated from rest through a potential difference of %s V. What is its final speed (non-relativistic)?" % (part, sci(V_)), v, [math.sqrt(qn * V_ / m_), v / 2, v * math.sqrt(2), v * 2], "m/s", ex("Energy conservation: $qV=\\tfrac12mv^2\\Rightarrow v=\\sqrt{\\dfrac{2qV}{m}}=\\sqrt{\\dfrac{2(1.602\\times10^{-19})(%s)}{%s}}=%s\\,\\mathrm{m/s}$." % (sci(V_), sci(m_), sci(v))), GEN(H3 + ", Q7"), "gen", sig=3)
    mcq_num(B, c, "Energy and potential difference", 1, "An electron moves through a potential difference of $200\\,\\mathrm{V}$. How much kinetic energy does it gain?", E_CH * 200.0, [200.0, E_CH / 200.0, E_CH * 200.0 * 2, E_CH * 200.0 / 2], "J", ex("$\\Delta K=-q\\Delta V=e(200\\,\\mathrm{V})=3.2\\times10^{-17}\\,\\mathrm{J}$ ($=200\\,\\mathrm{eV}$)."), GEN(H3 + ", Q7"), "gen", sig=3)
    mcq_num(B, c, "Potential and field", 1, "A uniform field of $400\\,\\mathrm{V/m}$ exists between two plates $2.5\\,\\mathrm{cm}$ apart. What is the potential difference between the plates?", 400.0 * 0.025, [400.0 / 0.025, 400.0 * 2.5, 0.025 / 400.0, 400.0 * 0.025 / 2], "V", ex("Uniform field: $\\Delta V=Ed=(400)(0.025)=10\\,\\mathrm{V}$ (convert $2.5\\,\\mathrm{cm}$ to metres)."), GEN(H3 + ", Q1"), "gen", sig=2)
    # disk / ring potential
    sg, Rd, z = 1.0e-6, 0.30, 0.20
    Vd = sg / (2 * EPS0) * (math.sqrt(Rd ** 2 + z ** 2) - z)
    check(Vd, disk_potential(sg, Rd, z, EPS0), 1e-6)
    mcq_num(B, c, "Potential of point charges", 3, "A disk of radius $0.30\\,\\mathrm{m}$ carries a uniform surface charge density $1.0\\,\\mu\\mathrm{C/m^2}$. What is the potential on its axis $0.20\\,\\mathrm{m}$ from its centre?", Vd, [k * sg * math.pi * Rd ** 2 / z, sg / (2 * EPS0) * (math.sqrt(Rd ** 2 + z ** 2) + z), sg / (2 * EPS0) * Rd, Vd * 2], "V", ex("Add the potentials of rings: $V=\\dfrac{\\sigma}{2\\varepsilon_0}\\left(\\sqrt{z^2+R^2}-z\\right)=\\dfrac{1.0\\times10^{-6}}{2(8.85\\times10^{-12})}(0.361-0.200)=9.1\\times10^{3}\\,\\mathrm{V}$.", "Numerical integration of the ring contributions gives the same value; treating the disk as a point charge ($k\\sigma\\pi R^2/z=1.3\\times10^{4}\\,\\mathrm{V}$) is too crude at $z=0.67R$."), GEN("Electrostatics lecture, 4.3 Calculations of potential"), "gen", sig=2)
    Rs, Qs = 0.15, 6.0e-9
    mcq_num(B, c, "Potential of conductors", 2, "A conducting sphere of radius $15\\,\\mathrm{cm}$ carries a charge of $6.0\\,\\mathrm{nC}$. What is its potential (with $V=0$ at infinity)?", k * Qs / Rs, [k * Qs / Rs ** 2, 0.0, k * Qs / Rs / 2, k * Qs * Rs], "V", ex("The sphere is an equipotential, equal to the value at its surface: $V=\\dfrac{kQ}{R}=\\dfrac{(8.99\\times10^9)(6.0\\times10^{-9})}{0.15}=3.6\\times10^{2}\\,\\mathrm{V}$ (also the value anywhere inside)."), GEN("Electrostatics lecture, 4.6 Potential of a charged isolated conductor"), "gen", sig=2)
    R1_, R2_ = 0.05, 0.15; Qt = 8.0e-9
