    mcq_num(B, c, "Potential and field", 1, "Two parallel plates $2.0\\,\\mathrm{cm}$ apart are held at a potential difference of $300\\,\\mathrm{V}$. What is the field between them?", 300.0 / 0.020, [300.0 * 0.020, 300.0 / 2.0, 300.0 * 2.0, 300.0 / 0.020 / 2], "V/m", ex("$E=\\dfrac{\\Delta V}{d}=\\dfrac{300}{0.020}=1.5\\times10^{4}\\,\\mathrm{V/m}$."), GEN(H3 + ", Q1"), "gen", sig=2)
    q, ra, rb = 8.0e-9, 0.20, 0.50
