    mcq_pick(B, c, "Potential and field", 1, "If the electric potential is constant throughout a region, the electric field there is", ["zero", "uniform and non-zero", "perpendicular to the region", "equal to $V/r$"], 0, ex("$\\vec E=-\\nabla V=0$ when $V$ does not vary."), LEC + ", 4.4", "concept")
    mcq_pick(B, c, "Energy and potential difference", 2, "A charge is moved along an equipotential surface from one point to another. The work done by the electric field is", ["zero", "$qE\\,d$", "positive for a positive charge", "equal to $qV$"], 0, ex("$W=-q\\Delta V=0$ since $\\Delta V=0$ between any two points of an equipotential surface (the field is perpendicular to the path)."), LEC + ", 4.2", "concept")
